<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$version=trim((string)($_POST['version']??''));$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$date=trim((string)($_POST['date']??date('Y-m-d')));$category=trim((string)($_POST['category']??'Release'));if(!$version||!preg_match('/^\d+\.\d+\.\d+$/',$version))$error='Use a semantic version.';elseif(!$title||strlen($title)<3)$error='Add a title.';elseif(!$description||strlen($description)<10)$error='Add a description.';elseif(!strtotime($date))$error='Choose a valid date.';else{$entries=load_json('changelog.json',[]);$entries[]= ['id'=>'chg-'.bin2hex(random_bytes(8)),'version'=>$version,'title'=>$title,'description'=>$description,'date'=>$date,'category'=>$category];if(save_json('changelog.json',$entries))$success='Changelog entry added.';else$error='The entry could not be saved.';}}?>
